        $index = $this->tokens->getPrevMeaningfulToken($index);
    }

    while ($this->tokens[$index]->isGivenKind(CT::T_ATTRIBUTE_CLOSE)) {
        $index = $this->tokens->findBlockStart(Tokens::BLOCK_TYPE_ATTRIBUTE, $index);
        $index = $this->tokens->getPrevMeaningfulToken($index);
    }

