        '$_GET' => true,
        '$_POST' => true,
        '$_REQUEST' => true,
        '$_SERVER' => true,
        '$_SESSION' => true,
        '$GLOBALS' => true,
    ];

    $token = $this->tokens[$index];

    if (!$token->isGivenKind(T_VARIABLE)) {
        return false;
    }

    return isset($superNames[strtoupper($token->getContent())]);
